const body = $input.first().json.body || {};
const path = String(body.path || '').replace(/^\/+/, '');
if (!path) { return [{ json: { ok: false, error: 'path is required' } }]; }
const urlPath = path.split('/').map(encodeURIComponent).join('/');
return [{ json: { ok: true, path, urlPath, ref: body.ref || 'main', maxChars: Number(body.maxChars || 0) } }];

const prep = $('Prepare').first().json;
const r = $input.first().json || {};
if (!r.content || r.type !== 'file') {
  return [{ json: { ok: false, path: prep.path, error: r.message || 'not a file or not found', status: r.status || null } }];
}
let text = Buffer.from(String(r.content).replace(/\n/g, ''), 'base64').toString('utf8');
const total = text.length;
let truncated = false;
if (prep.maxChars > 0 && total > prep.maxChars) { text = text.slice(0, prep.maxChars); truncated = true; }
return [{ json: { ok: true, path: prep.path, sha: r.sha, size: r.size, chars: total, truncated, content: text } }];
